SELECT                                                                                                             
cx_cirugia.cirugia,
cx_cirugia.registro,
cx_cirugia.fecha AS FECHA_CX,
 
		(select servicio.servicio from cx_cirugia_procedimiento, servicio 
				where
				servicio.concepto ='PRQX' AND
				 cx_cirugia.cirugia = cx_cirugia_procedimiento.cirugia and 
						cx_cirugia_procedimiento.servicio = servicio.servicio 
			order by cx_cirugia_procedimiento.numero_uvr desc ,cx_cirugia_procedimiento.grupo desc   limit 1 offset 0) as Cups1,

	(select servicio.descripcion from cx_cirugia_procedimiento , servicio 
				where 
		 		servicio.concepto ='PRQX' AND
				cx_cirugia.cirugia = cx_cirugia_procedimiento.cirugia and
						cx_cirugia_procedimiento.servicio = servicio.servicio 
			order by cx_cirugia_procedimiento.numero_uvr desc ,cx_cirugia_procedimiento.grupo desc   limit 1 offset 0) as qx1,

(select usuario.USUARIO FROM usuario, especialidad where especialidad.especialidad = usuario.especialidad and cx_cirugia.usuario_cirujano = usuario.usuario) As Doc_Cirujano,
(select usuario.nombre FROM usuario, especialidad where especialidad.especialidad = usuario.especialidad and cx_cirugia.usuario_cirujano = usuario.usuario) As Cirujano,
(select especialidad.descripcion FROM usuario, especialidad where especialidad.especialidad = usuario.especialidad and cx_cirugia.usuario_cirujano = usuario.usuario) As Espec,

(CASE
    WHEN (select especialidad.descripcion FROM usuario, especialidad where especialidad.especialidad = usuario.especialidad and cx_cirugia.usuario_cirujano = usuario.usuario) = 'RADIOLOGIA' THEN 'PROCEDIMIENTOS MENORES'
    WHEN (select especialidad.descripcion FROM usuario, especialidad where especialidad.especialidad = usuario.especialidad and cx_cirugia.usuario_cirujano = usuario.usuario) = 'DERMATOLOGIA' THEN 'PROCEDIMIENTOS MENORES'
    WHEN (select servicio.servicio from cx_cirugia_procedimiento, servicio 
	        where
		servicio.concepto ='PRQX' AND
		cx_cirugia.cirugia = cx_cirugia_procedimiento.cirugia and 
		cx_cirugia_procedimiento.servicio = servicio.servicio 
		order by cx_cirugia_procedimiento.numero_uvr desc ,cx_cirugia_procedimiento.grupo desc   limit 1 offset 0
	) IN ('012502',
