sum(mov_detalle.precio) as valor,
MAX(mov_encabezado.fecha_actualizacion) AS ULTIMA_FECHA_CARGUE,
(SELECT USUARIO.NOMBRE FROM USUARIO,mov_encabezado ME,mov_detalle MD
WHERE USUARIO.USUARIO = ME.USUARIO AND
  ME.bodega = MD.bodega and
  ME.tipo_transaccion= MD.tipo_transaccion and
  ME.consecutivo =MD.consecutivo and
  MD.ARTICULO = mov_detalle.articulo AND
  ME.CIRUGIA = mov_encabezado.CIRUGIA
  
  ORDER BY ME.fecha_actualizacion DESC LIMIT 1
 ) AS USUARIO_ULTIMO_MOVIMIENTO

--mov_encabezado.USUARIO AS USUARIO_CARGA,
--(SELECT USUARIO.NOMBRE FROM USUARIO WHERE USUARIO.USUARIO = mov_encabezado.USUARIO) AS USUARIO_CARGA,
 

FROM mov_encabezado,mov_detalle,cx_cirugia
   
WHERE    
  mov_encabezado.bodega = mov_detalle.bodega and
  mov_encabezado.tipo_transaccion= mov_detalle.tipo_transaccion and 
  mov_encabezado.consecutivo = mov_detalle.consecutivo and
mov_encabezado.CIRUGIA = cx_cirugia.cirugia   
 
--AND cx_cirugia.registro='1767908'
--AND mov_detalle.articulo='MC00793'
AND mov_encabezado.fecha_actualizacion between '2026/01/01 00:00:00' and CURRENT_TIMESTAMP

GROUP BY 
cx_cirugia.cirugia,
mov_encabezado.CIRUGIA, 
cx_cirugia.registro,
cx_cirugia.fecha,
mov_detalle.articulo--,
--mov_encabezado.fecha_actualizacion,
--mov_encabezado.USUARIO

--HAVING sum(mov_detalle.precio)>300000

ORDER BY valor desc